def seed_existing_organization_hierarchy(apps, schema_editor):
    """Project existing Company/Department facts into OrganizationUnit without inventing facts."""
    Company = apps.get_model('system', 'Company')
    Department = apps.get_model('system', 'Department')
    OrganizationUnit = apps.get_model('system', 'OrganizationUnit')

    company_units = {}
    for company in Company.objects.all().order_by('pk'):
        unit, _ = OrganizationUnit.objects.update_or_create(
            company_id=company.pk,
            code=f'COMP-{company.code}',
            defaults={
                'name': company.name,
                'unit_type': 'COMPANY',
                'parent_id': None,
                'is_active': company.is_active,
            },
        )
        company_units[company.pk] = unit

    department_units = {}
    for department in Department.objects.all().order_by('pk'):
        unit, _ = OrganizationUnit.objects.update_or_create(
            company_id=department.company_id,
            code=f'DEPT-{department.code or department.pk}-{department.pk}',
            defaults={
                'name': department.name,
                'unit_type': 'DEPARTMENT',
                'parent_id': company_units[department.company_id].pk,
                'is_active': department.is_active,
            },
        )
        department_units[department.pk] = unit

    for department in Department.objects.all().order_by('pk'):
        unit = department_units[department.pk]
        expected_parent = (
            department_units.get(department.parent_id)
            if department.parent_id
            else company_units[department.company_id]
        )
        if expected_parent and unit.parent_id != expected_parent.pk:
            unit.parent_id = expected_parent.pk
            unit.save(update_fields=['parent'])
        Department.objects.filter(pk=department.pk).update(organization_unit_id=unit.pk)


